def _canon_days(o):
    """A sitting-days answer as plain data, to compare two: dict and list
    order kept, a set as a set, a Day or Item field by field."""
    if isinstance(o, dict):
        return ("dict", [(_canon_days(k), _canon_days(v)) for k, v in o.items()])
    if isinstance(o, (list, tuple)):
        return (type(o).__name__, [_canon_days(v) for v in o])
    if isinstance(o, (set, frozenset)):
        return ("set", sorted(repr(_canon_days(v)) for v in o))
    if hasattr(type(o), "__slots__") or hasattr(o, "__dict__"):
        slots = [s for c in type(o).__mro__ for s in getattr(c, "__slots__", ())]
        d = {s: _canon_days(getattr(o, s, "<unset>")) for s in slots}
        if hasattr(o, "__dict__"):
            d.update({k: _canon_days(v) for k, v in vars(o).items()})
        return (type(o).__name__, sorted(d.items()))
    return o


@check("session", "the sitting days are worked out once a build: kept, read back as the parse "
       "gives them, worked out again when an input moves or the file will not read",
       needs=("narrative", "session_days"))
def _session_days_cache(N, SD):
    """session_days.load() was the same half-minute parse in four steps of
    the build and the night's checks (29 October 2026); the build's own call
    now keeps its answer in .build_cache/session_days.pkl.gz under a sha256
    of every file it read, every folder it listed, every path it looked for
    and its code, and the steps after it read it back. This holds the four
    things that make that safe: what is read back is what the parse gives,
    the days the voting system began included; a byte moved in an input, or
    a file added where the parse looks, is a miss; a cache that will not
    read is worked out again with the same answer; and a check's call, which
    names its own record, is never kept."""
    narr = {}
    for term, bill, lines, _want in _DOCKET_INTRODUCED_ADOPTED:
        if term == "2025-2026":
            narr.setdefault(term, {})[bill] = {
                "events": _told_from_rows(N, term, bill, lines)["events"]}
    here, d = Path.cwd(), Path(tempfile.mkdtemp(prefix="sd_cache_"))
    began = dict(SD.ROLLCALLS_FROM)
    try:
        (d / "narratives.json").write_text(json.dumps(narr), encoding="utf-8")
        (d / "rollcalls.json").write_text(json.dumps({"2025-2026": {"HR1": [_rc(
            "1998", "H", 1, "1998-06-02", "HR1", "Adoption", 300, 10, True)]}}),
            encoding="utf-8")
        os.chdir(d)
        # The build's call, on this record and with no Journals: load() gives
        # _cached a call of _load, and a check that read the Journals on disk
        # would fail _session_checks_read_no_journals.
        work = lambda: SD._load(SD.NARRATIVES, sat=lambda body, date: False, journals={})
        cold = SD._cached(work)
        kept = d / ".build_cache" / SD.CACHE_FILE
        assert kept.exists(), "the build's call kept nothing"
        SD.ROLLCALLS_FROM.clear()
        warm, why = SD.load_cache()
        assert warm is not None, f"the kept days were not read back: {why}"
        assert SD.ROLLCALLS_FROM == {"H": "1998-06-02", "S": SD.ROLLCALLS_BEGIN["S"]}, (
            f"the days the voting system began were not read back: {SD.ROLLCALLS_FROM}")
        fresh = work()
        assert _canon_days(warm) == _canon_days(fresh) == _canon_days(cold), (
            "the days read back are not the days the parse gives")
        n = (d / "narratives.json").read_text(encoding="utf-8")
        (d / "narratives.json").write_text(n + " ", encoding="utf-8")
        assert SD.load_cache()[0] is None, "a moved input was read from the cache"
        (d / "narratives.json").write_text(n, encoding="utf-8")
        assert SD.load_cache()[0] is not None, "the input put back missed"
        # A folder the parse listed that was not there, and a path it looked
        # for and did not find, are keys too: the first Journal of a new
        # year is a folder that appears (the build's own call lists the
        # year folders; this record reads none, so the key is asked here).
        inputs = {"files": [], "dirs": [str(d / "j" / "2024")], "looked": [str(d / "k.txt")]}
        before = SD._inputs_key(inputs)
        (d / "j" / "2024").mkdir(parents=True)
        assert SD._inputs_key(inputs) != before, "a folder that appeared did not move the key"
        (d / "j" / "2024").rmdir()
        assert SD._inputs_key(inputs) == before, "the key moved with nothing changed"
        (d / "k.txt").write_text("", encoding="utf-8")
        assert SD._inputs_key(inputs) != before, "a path that appeared did not move the key"
        (d / "k.txt").unlink()
        kept.write_bytes(kept.read_bytes()[:200])
        assert SD.load_cache()[0] is None, "a cache cut short was read"
        again = SD._cached(work)
        assert _canon_days(again) == _canon_days(fresh), "worked out again, the days differ"
        kept.unlink()
        SD.load(d / "narratives.json", sat=lambda body, date: False, journals={})
        assert not kept.exists(), "a call naming its own record kept its answer"
        # THE RECORDING ITSELF (the review of 29 October 2026). Memos a step
        # filled before load() are emptied, or the files they came from
        # would be missing from the key; a path asked through Path.exists,
        # is_dir or os.path.isfile -- what Windows asks without os.stat --
        # is looked for; a file opened to write is no input.
        memos = [getattr(sys.modules.get(m), n, None) for m, n in SD._Inputs.MEMOS]
        for memo in memos:
            if isinstance(memo, dict):
                memo["filled before"] = True

        def asks():
            Path("gone-a").exists()
            Path("gone-b").is_dir()
            os.path.isfile("gone-c")
            (d / "written.txt").write_text("x", encoding="utf-8")
            # Read by its keys, not asked with `in`: _session_checks_read_no_
            # journals counts every `in` asked of _SAT as a Journal read.
            return [isinstance(m, dict) and any(k == "filled before" for k in list(m))
                    for m in memos]
        left, inputs = SD._Inputs.record(asks)
        assert not any(left), f"a memo filled before the parse was not emptied: {left}"
        assert {"gone-a", "gone-b", "gone-c"} <= set(inputs["looked"]), (
            f"a path asked of without os.stat was not looked for: {inputs['looked']}")
        assert not any("written.txt" in f for f in inputs["files"] + inputs["looked"]), (
            "a file written was taken for an input")
    finally:
        os.chdir(here)
        SD.ROLLCALLS_FROM.clear()
        SD.ROLLCALLS_FROM.update(began)
        shutil.rmtree(d, ignore_errors=True)
    return "ok", "kept, read back alike, missed on a moved byte and a new file, worked out again"


@check("narrative", "a resolution introduced and adopted in one motion is told as adopted that day, "
                    "and its chamber's sitting is drawn", needs=("narrative", "session_days"))
def _introduced_and_adopted(N, SD):
    """From 2007 the docket's "Introduced and Adopted VV 12/04/2024" -- HR 1
    to HR 5 and SR 1 to SR 5 of each Organization Day, 172 rows -- was read as
    nothing, so those resolutions had no history and no sitting page was drawn
    for 4 December 2024. Read as the reader of 1999-2006 reads the same words,
    the chamber adopting it, and told in the sentence every adopted
    resolution's passage has. Not where the chamber passes it on a row of its
    own: HR 16 of 2020's row is the motion to introduce, and its passage is
    "Ought to Pass : MA DV 316-10", told once, as before."""
    bad, narr = [], {}
    for term, bill, lines, want in _DOCKET_INTRODUCED_ADOPTED:
        n = _told_from_rows(N, term, bill, lines)
        said = n.get("narrative") or ""
        if want is not None and said != want:
            bad.append(f"{bill} of {term} is told {said!r}, not {want!r}")
        if want is None and (said.count("voted to pass it") != 1
                             or any(e["type"] == "floor" and "Introduced and Adopted" in e["raw"]
                                    for e in n["events"])):
            bad.append(f"{bill} of {term}'s motion to introduce is told as its passage: {said!r}")
        narr.setdefault(term, {})[bill] = n["events"]
    try:
        days = _sitting_fixture(SD, {"2025-2026": narr["2025-2026"]}, {})
    except (AssertionError, SystemExit) as e:
        days = {}
        bad.append(f"no sitting is drawn from 2025's resolutions: {e}")
    for body, bill in (("H", "HR1"), ("S", "SR1")):
        day = days.get((body, "2024-12-04"))
        if day is None or not any(i.bill == bill for i in day.items):
            bad.append(f"no {body} sitting of 4 December 2024 draws {bill}: {sorted(days)}")
    # A day before the bill's term is the clerk's slip, not a sitting
    # (narrative._adopted_in_term): HR 6 of 2021, Docket_2021-2022.txt line
    # 13807, adopted on 6 January 2021 and typed 2020.
    n = _told_from_rows(N, "2021-2022", "HR6", [
        "2021|1064|1/7/2021 12:00:00 AM|HR6|H|Introduced and Adopted VV 01/06/2020 HJ 2 P. 2|1/7/2021 12:00:00 AM"])
    if any(e["type"] == "floor" for e in n["events"]):
        bad.append(f"HR 6 of 2021's row dated 6 January 2020 is told as a sitting's: {n['events']!r}")
    else:
        try:
            gone = _sitting_fixture(SD, {"2021-2022": {"HR6": n["events"]}}, {})
        except (AssertionError, SystemExit):
            gone = {}
        if ("H", "2020-01-06") in gone:
            bad.append("a House sitting of 6 January 2020 is drawn from HR 6 of 2021")
    assert not bad, "\n".join(bad)
    return "ok", ("HR 1 and SR 1 of 2025 and HR 1 of 2007 told as adopted, both chambers' sittings "
                  "of 4 December 2024 drawn, HR 16 of 2020's motion to introduce left as it was, "
                  "and HR 6 of 2021's row typed 2020 drawn on no sitting")


@check("build", "a recent docket row carries its own sentence for Latest Activity, and an old one "
       "does not", needs=("narrative",))
def _row_said(N):
    """The person's list, 10 October 2026: the home page's Latest Activity
    showed the clerk's line as typed. Each row of the last SAID_DAYS carries
    the sentence the history first tells it in (`told`), which build_site_v2
    puts there instead; older rows carry none, so narratives.json does not
    grow by every term's sentences. SB 387 of 2000's real rows, built as of
    1 March 2000 and again as of today."""
    import datetime as _dt
    rows = [x for x in _DOCKET_TIME_CHANGE if "|SB387|" in x]
    was = N.TODAY
    try:
        N.TODAY = _dt.date(2000, 3, 1)
        then = _told_from_rows(N, "1999-2000", "SB387", rows)
        N.TODAY = _dt.date(2026, 10, 10)
        now = _told_from_rows(N, "1999-2000", "SB387", rows)
    finally:
        N.TODAY = was
    said = [e.get("told") for e in then["events"] if not e.get("cancelled")]
    assert said and all(isinstance(s, str) and s.endswith(".") for s in said if s) and any(said), (
        f"rows a week old carry no sentence: {said!r}")
    assert not any(e.get("told") for e in now["events"]), (
        "rows of 2000, built in 2026, carry a sentence they do not need")
    # NOT `said`, which is the clerk's line with its cancel mark (marked_line)
    # and what a bill's docket list prints: a sentence there would replace the
    # docket's own lines on every bill page.
    assert not any(e.get("said") and e.get("said") == e.get("told") for e in then["events"]), (
        "the row's sentence went into `said`, the docket list's line")
    return "ok", f"{sum(1 for s in said if s)} rows of February 2000 say themselves, as of March 2000"


# The day the person made the Secretary of State the source and kept
# Ballotpedia's figures beside every row the voters had decided by then: an
# election after it is a row that never had Ballotpedia as its source.
_BALLOT_CROSS_CHECKED = "2026-10-07"


@check("status", "the two No counts the person corrected on 7 October 2026 are the Secretary "
                 "of State's, and Ballotpedia's are kept beside every row decided by then")
def _ballot_corrected_counts():
    """The person's decision of 7 October 2026 on ballot_results.json, their
    file: the Secretary of State's count is every decided row's, and the two
    No counts where Ballotpedia's list -- the file's source until then --
    differs are the Secretary of State's. CACR 7 of 1992: 204,475, which the
    Manual for the General Court 1993 prints on p. 442, its town table sums
    to and the docket's referendum line says, where Ballotpedia has 204,457.
    CACR 41 of 2006: 100,688, the Manual 2007's p. 335 and its county summary
    on p. 336, where Ballotpedia has 100,686. Neither changes the outcome.

    Ballotpedia's figures stay on each decided row as the cross-check
    (`ballotpedia`), and on the other fifteen they are the Secretary of
    State's to the vote, so a count that moves by itself is caught here too.
    Fails on either corrected row holding another No, on its cross-check
    losing Ballotpedia's figure, on a row decided by 7 October 2026 with no
    cross-check, and on any other decided row whose count is not its
    cross-check's.

    A ROW DECIDED AFTER THAT DAY NEEDS NO CROSS-CHECK. CACR 13 of 2025-2026
    goes to the voters on 3 November 2026, and its note says it then takes
    the Secretary of State's count like the others; this check asked every
    decided row for Ballotpedia's figures too, so the person's November entry
    would have failed preflight until somebody went and read Ballotpedia (the
    review of 7 October 2026). It is compared only where it has them."""
    rows = _ballot_file()
    bad = []
    for key, no, bp in ((("1991-1992", "CACR7"), 204475, 204457),
                        (("2005-2006", "CACR41"), 100688, 100686)):
        r = rows.get(key) or {}
        cross = r.get("ballotpedia") or {}
        if r.get("no") != no:
            bad.append(f"{key[1]} of {key[0]}'s No is {r.get('no')!r}, not the Secretary of "
                       f"State's {no:,}")
        if cross.get("no") != bp:
            bad.append(f"{key[1]} of {key[0]}'s cross-check reads No {cross.get('no')!r}, not "
                       f"Ballotpedia's {bp:,}")
    same, later = 0, 0
    for key, r in sorted(rows.items()):
        if r.get("yes") is None or key in (("1991-1992", "CACR7"), ("2005-2006", "CACR41")):
            continue
        cross = r.get("ballotpedia")
        if not isinstance(cross, dict) and str(r.get("election") or "") > _BALLOT_CROSS_CHECKED:
            later += 1
            continue
        if not isinstance(cross, dict):
            bad.append(f"{key[1]} of {key[0]} keeps no Ballotpedia figures to cross-check")
        elif (cross.get("yes"), cross.get("no")) != (r.get("yes"), r.get("no")):
            bad.append(f"{key[1]} of {key[0]} reads {r.get('yes')!r} to {r.get('no')!r} and "
                       f"Ballotpedia {cross.get('yes')!r} to {cross.get('no')!r}")
        else:
            same += 1
    assert not bad, "; ".join(bad[:5])
    return "ok", (f"CACR 7 of 1992 No 204,475 and CACR 41 of 2006 No 100,688, Ballotpedia's "
                  f"204,457 and 100,686 kept beside them; the other {same} decided rows equal "
                  "their cross-check" + (f"; {later} decided after 7 October 2026 carry none, "
                                          "and need none" if later else ""))


@check("status", "every amendment the voters decided cites the Secretary of State's count, "
                 "and the one to come names its own source")
def _ballot_sources():
    """Since 7 October 2026 (the person's decision) a row the voters have
    decided reads its count from the Secretary of State: its results page on
    sos.nh.gov from 2016, when that site's results begin, and NHPR's scan of
    the page of the Department of State's Manual for the General Court that
    prints it before then (electiondatabase.nhpr.org) -- with `cite` saying
    where, in words a reader can look up. Every decided row named Ballotpedia
    until then. The election still to come keeps the list that names it
    (Ballotpedia's) and says so; it needs a source and a label and no more.

    Fails on a decided row whose source is on any other host, or which has
    no cite; on one still carrying the separate `sos` object the Secretary of
    State's figures were folded in from; and on a row of either kind naming
    no source."""
    rows = _ballot_file()
    from urllib.parse import urlparse
    hosts = Counter()
    bad, to_come = [], []
    for key, r in sorted(rows.items()):
        name = f"{key[1]} of {key[0]}"
        src = str(r.get("source") or "")
        host = re.sub(r"^www\.", "", urlparse(src).hostname or "")
        if not src.startswith("https://") or not host:
            bad.append(f"{name} names no source")
            continue
        if r.get("yes") is None:
            to_come.append(f"{name} ({host})")
            continue
        if host not in ("sos.nh.gov", "electiondatabase.nhpr.org"):
            bad.append(f"{name}'s count is read from {host}, not the Secretary of State")
        if not (isinstance(r.get("cite"), str) and r["cite"].strip()):
            bad.append(f"{name} cites nothing")
        if "sos" in r:
            bad.append(f"{name} still carries the Secretary of State's figures apart, in sos")
        hosts[host] += 1
    assert not bad, "; ".join(bad[:5])
    assert hosts, "ballot_results.json holds no decided row"
    return "ok", (f"{sum(hosts.values())} decided rows cite the Secretary of State ("
                  + ", ".join(f"{k} on {h}" for h, k in hosts.most_common()) + "); to come: "
                  + (", ".join(to_come) or "none"))


