# Each record's own LSR, as data/bills.json gives it.
LSRS_OWN = {
    "1989-1990": {"SCR2": ("1990", "2730"), "SR8": ("1990", "2755"),
                  "HB1": ("1989", "9100")},
    "1991-1992": {"HCR15": ("1992", "1230")},
    "1995-1996": {"HB306": ("1996", "166"), "HB1637": ("1996", "2936")},
    "1999-2000": {"HB1101": ("2000", "2038")},
    "2001-2002": {"HR24": ("2002", "2458")},
    "2011-2012": {"SB98": ("2011", "960"), "SB99": ("2011", "961"),
                  "SR3": ("2011", "1127")},
}


@check("narrative", "a bill's history is read from the rows carrying its own LSR",
       needs=("narrative",))
def _narrative_own_lsr(N):
    """The docket's bill-number field put another measure's events in 43
    archived histories, and 59 bills' own rows under keys no bill carries.
    1990's SCR 2, the Fast Day resolution the Senate killed, said the House
    passed it on 13 April 1989: that was the 1989 recycling resolution under
    the same number. Each shape below is one way it could come back, on rows
    copied from the dockets -- and the CLI is run both ways the pipeline runs
    it, because a rule the build never asks for is no rule."""
    def ok(rows, bill):
        return [r["desc"] for r in rows.get(bill, [])]

    tmp = Path(tempfile.mkdtemp())
    try:
        got, report = {}, {}
        for term, lines in DOCKETS_OWN_LSR.items():
            p = tmp / f"Docket_db_{term}.txt"
            p.write_text("\n".join(lines) + "\n", encoding="utf-8")
            N.LSR_REPORT.update(taken=[], moved=[])
            got[term] = N.parse_docket(str(p), lsrs=LSRS_OWN)
            report[term] = (len(N.LSR_REPORT["taken"]), len(N.LSR_REPORT["moved"]))
        g = got["1989-1990"]
        assert [r["lsr"] for r in g["SCR2"]] == ["1990-2730"] * 2, (
            "1990's SCR 2 still carries the 1989 resolution's rows: "
            f"{[r['lsr'] for r in g['SCR2']]}")
        assert len(g.get("SSHB1", [])) == 2 and all("SPEC COMM" not in d for d in ok(g, "SR8")), (
            "1989-1990's SSHB1 rows -- the only place the sitting's page gets HB 1's 217-147 "
            "roll call -- were dropped, or moved onto SR 8, whose LSR they wrongly carry")
        assert len(got["1991-1992"]["HCR15"]) == 4, (
            "HCR 15 lost the rows its one LSR carries into the term's other year")
        g = got["1995-1996"]
        assert len(g.get("HB 0306", [])) == 1 and not any("JUDICIARY" in d for d in ok(g, "HB1637")), (
            "HB 306's July 1995 work sessions were given to HB 1637, the welfare bill of 1996, "
            "because the row carries HB 1637's LSR")
        g = got["1999-2000"]
        assert "1101" not in g and any(d.startswith("Introduced") for d in ok(g, "HB1101")), (
            "HB 1101's introduction stayed under the key '1101'")
        assert any(d.startswith("Copy to Chairman") for d in ok(g, "HB1101")), (
            "a row with no LSR was left out of the bill it was filed under")
        g = got["2001-2002"]
        assert "" not in g and any(d.startswith("Introduced") for d in ok(g, "HR24")), (
            "HR 24's introduction stayed under a blank number")
        assert len(got["2009-2010"].get("HB1308", [])) == 2, (
            "a bill with no record lost rows whose LSR names no bill")
        g = got["2011-2012"]
        assert [r["lsr"] for r in g["SB98"]] == ["2011-0960"] * 2, (
            "SB 98 still carries SB 99's introduction")
        assert not any(d.startswith("Introduced") for d in ok(g, "SB99")), (
            "SB 99 was given the row its LSR names -- moving it corrects the General "
            "Court's own record, which is the person's decision")
        assert len(g["SR3"]) == 3, (
            "SR 3's second organization-day LSR lost the select committee rows it holds")
        assert report == {"1989-1990": (3, 0), "1991-1992": (0, 0), "1995-1996": (0, 0),
                          "1999-2000": (0, 1), "2001-2002": (0, 1), "2009-2010": (0, 0),
                          "2011-2012": (1, 0)}, f"what own_rows says it did: {report}"
        # No bill list: every row stays where the clerk filed it.
        bare = N.parse_docket(str(tmp / "Docket_db_1989-1990.txt"))
        assert len(bare["SCR2"]) == 5 and len(bare["SSHB1"]) == 2, (
            "with no bill list, rows were chosen anyway")

        # The two ways the pipeline asks. build_all narrates the current term
        # with narrative.py's own default list, data/bills.json ...
        (tmp / "data").mkdir()
        (tmp / "data" / "bills.json").write_text(json.dumps({
            t: {b: {"lsr": f"{y}-{n}", "lsr_year": y, "lsr_num": n}
                for b, (y, n) in recs.items()} for t, recs in LSRS_OWN.items()}),
            encoding="utf-8")
        (tmp / "Docket.txt").write_text(
            "\n".join(DOCKETS_OWN_LSR["2011-2012"]) + "\n", encoding="utf-8")
        r = _run([sys.executable, _paths.script("narrative.py"), "--docket",
                  "Docket.txt", "--all", "--out", "cur.json"],
                 cwd=tmp, capture_output=True, text=True, timeout=300)
        assert r.returncode == 0, "narrative.py failed: " + (r.stderr or r.stdout)[-300:]
        assert "rows by LSR" in r.stdout, "narrative.py did not say what the LSRs did"
        cur = json.loads((tmp / "cur.json").read_text(encoding="utf-8"))["2011-2012"]
        assert len(cur["SB98"]["events"]) == 2, (
            "narrative.py with its default bill list still told SB 99's introduction on SB 98")
        # ... and narrate_archive the archive, passing its own --bills on --
        # given as a full path, which on Windows carries a drive letter's
        # colon into the line the archive's total is read from.
        (tmp / "Docket.txt").unlink()
        (tmp / "data" / "bills.json").rename(tmp / "lsrs.json")
        r = _run([sys.executable, _paths.script("narrate_archive.py"),
                  "--out", "arch.json", "--bills", str((tmp / "lsrs.json").resolve())],
                 cwd=tmp, capture_output=True, text=True, timeout=300)
        assert r.returncode == 0, "narrate_archive.py failed: " + (r.stderr or r.stdout)[-300:]
        arch = json.loads((tmp / "arch.json").read_text(encoding="utf-8"))
        # The terms run several at a time and are merged in their order, so
        # the file is the one runs one after another wrote, whichever term
        # finished first (narrate_archive.WORKERS).
        assert len(arch) > 1 and list(arch) == sorted(arch), \
            ("the archive's terms were merged out of their order", list(arch))
        scr2 = arch["1989-1990"]["SCR2"]
        assert "SSHB1" in arch["1989-1990"] and "1101" not in arch["1999-2000"] and \
            "HB 0306" in arch["1995-1996"] and \
            not any("1989" in (e.get("date") or "") for e in scr2["events"]), (
            "narrate_archive did not pass --bills on: 1990's SCR 2 says "
            f"{scr2['narrative'][:90]!r}")
        assert "rows by LSR" in r.stdout, "narrate_archive did not pass on what the LSRs did"
        assert "rows by LSR, every term: 4 row(s) left out of 2 histories" in r.stdout, (
            "narrate_archive's all-term total is missing or wrong: "
            + " | ".join(l for l in r.stdout.splitlines() if "rows by LSR" in l)[-300:])
        return "ok", ("a reused number and another bill's LSR leave the history; SR 8's LSR "
                      "on SSHB1 and HB 1637's on HB 306's rows move nothing; HCR 15 keeps both "
                      "years, SR 3 both entries, a row with no LSR its bill; a blank, bare or "
                      "mistyped key goes to its LSR's bill; both pipeline paths")
    finally:
        N.LSR_REPORT.update(taken=[], moved=[])
        shutil.rmtree(tmp, ignore_errors=True)


@check("session", "a speech is not credited to a motion made after it, and a credited "
       "speaker is not listed again as unplaced",
       needs=("narrative", "journal_days", "session_days", "build_session_pages"))
def _session_speech_before_its_motion(N, JD, SD, BSP):
    """The vote a speech precedes ties it to a motion, and the House often
    puts another motion between the two. On 9 June 1999 Rep. Arndt moved that
    the House concur with the Senate's amendment to HB 374 and spoke in
    favor; Rep. Rice moved to table; the roll call, 62-273, was on the
    tabling. While the 1999-2006 docket's lost motions carried no count there
    was nothing to tie such a speech to; read with their counts, sixteen
    tabling motions, a postponement and a special order of those years each
    took the speeches made before them, and the same reading had long put
    speeches on motions made after them in every other year (on 4 January
    2024, two members who spoke on an amendment to HB 232 under the motion
    that then tabled it). The journal says what was moved after a speech, and
    a motion of that kind does not claim it.

    A motion of ANOTHER kind made between does not untie a speech: HR 20 of
    2000's report was debated, a motion to table it lost on a division, and
    the roll call that followed, 162-179, was on the report.

    And the page's "also spoke during this bill" list named every speech each
    motion did not claim, motion by motion, so a member credited under one
    motion was listed again under "the record does not say which of the
    day's motions" because the motion beside it did not claim the speech
    too."""
    import html as _html
    attrs = JD.attributions(JD.clean(_JOURNAL_MOTION_AFTER))
    by = {}
    for a in attrs:
        for n in a["names"]:
            by.setdefault(n, []).append(a)
    arndt, = by["Arndt"]
    assert arndt["tally"] == (62, 273) and len(arndt["moved_since"]) == 1 and \
        "be laid on the table" in arndt["moved_since"][0], (
        f"the motion to table made after Rep. Arndt spoke is not kept with the speech: {arndt}")
    assert by["Kurk"][0]["tally"] == (50, 302) and by["Kurk"][0]["moved_since"] == [] and \
        by["Mirski"][0]["moved_since"] == ["Re-commit to Committee"], (
        f"HB 110's motion to recommit is not after Mirski's speech and before Kurk's: "
        f"{by['Mirski'][0]} {by['Kurk'][0]}")
    johnson = by["Gary Johnson"][0]
    assert johnson["tally"] == (162, 179) and len(johnson["moved_since"]) == 1, johnson

    def item(bill, term, action, motion, kind, y=None, n=None):
        return SD.Item(bill, term, {"type": "floor", "body": "H", "action": action,
                                    "motion": motion, "vote_kind": kind, "yeas": y, "nays": n,
                                    "raw": action}, 0)
    # HB 374: the tabling that lost 62-273, and the concurrence by voice.
    table = item("HB374", "1999-2000", "Lay on Table", "ML", "RC", "62", "273")
    concur = item("HB374", "1999-2000", "Concur", "MA", "VV")
    for sole in (False, True):
        mine, rest = BSP.speakers_for(attrs, "HB374", table, sole=sole)
        assert mine == {"for": [], "against": []} and rest["for"] == ["Arndt"], (
            f"Rep. Arndt, who spoke for concurring, is credited to the motion to table "
            f"HB 374 (one motion that day: {sole}): {mine}")
    assert BSP.unplaced(attrs, "HB374", [table, concur]) == ["Arndt"], (
        BSP.unplaced(attrs, "HB374", [table, concur]))
    # HR 20: a tabling motion between the debate and the vote on the report
    # does not take the debate from the report.
    report = item("HR20", "1999-2000", "Ought to Pass", "ML", "RC", "162", "179")
    tabled = item("HR20", "1999-2000", "Lay on Table", "ML", "DV", "156", "185")
    mine, _rest = BSP.speakers_for(attrs, "HR20", report)
    assert mine == {"for": ["Buckley", "Ronald Nowe"],
                    "against": ["Gary Johnson", "Jacobson", "Richard Herman", "Potter"]}, (
        f"HR 20's debate on the report, voted 162-179 after a tabling motion lost, is no "
        f"longer the report's: {mine}")
    assert BSP.speakers_for(attrs, "HR20", tabled)[0] == {"for": [], "against": []}
    assert BSP.unplaced(attrs, "HR20", [tabled, report]) == [], (
        f"HR 20's speakers, credited under the report, are listed again as unplaced: "
        f"{BSP.unplaced(attrs, 'HR20', [tabled, report])}")
    # CACR 34: the motion to table it is read past the period in its title.
    balboni = by["Balboni"][0]
    assert balboni["tally"] == (55, 277) and [m[-20:] for m in balboni["moved_since"]] == \
        ["be laid on the table"], (
        f"the motion to table CACR 34, whose title holds a period, is read as {balboni}")
    lay34 = item("CACR34", "2005-2006", "Lay on Table", "ML", "RC", "55", "277")
    assert BSP.speakers_for(attrs, "CACR34", lay34)[0] == {"for": [], "against": []} and \
        BSP.unplaced(attrs, "CACR34", [lay34]) == ["Balboni", "Desmarais", "Sorg"], (
        "those who spoke on CACR 34's report are credited to the motion to table it: "
        f"{BSP.speakers_for(attrs, 'CACR34', lay34)[0]}")
    # HB 110, on the page: Rep. Kurk spoke after the motion to recommit was
    # made, and the three before it spoke on the committee's report.
    saved = (N.CORRECTIONS, N.TERM)
    try:
        N.CORRECTIONS = []
        N.TERM = "1999-2000"
        rec = N.build("HB110", _docket_rows(_DOCKET_CUT_1999["HB110"]))
    finally:
        N.CORRECTIONS, N.TERM = saved
    root = Path(tempfile.mkdtemp())
    try:
        (root / "narratives.json").write_text(
            json.dumps({"1999-2000": {"HB110": {"events": rec["events"]}}}), encoding="utf-8")
        day = SD.load(root / "narratives.json", journals={})[("H", "1999-02-10")]
        nobody = type("Nobody", (), {"slug": lambda self, body, name: None})()
        page = BSP.render(day, {"attributions": attrs}, {}, {}, nobody, _html.escape)[0]
    finally:
        shutil.rmtree(root, ignore_errors=True)
    txt = re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", page))
    # Each side's names are their own paragraph (.sspoke), read to its end:
    # what follows one is the next motion's card, whatever its words. The
    # label says which vote the side urged (the owner, 24 October 2026).
    claimed = [(side, re.sub(r"\s+", " ", re.sub(r"<[^>]+>", " ", who)).strip())
               for side, who in re.findall(r'<p class="sspoke"><span class="slab">Spoke '
                                           r'(for|against) the motion, urging a (?:yes|no) '
                                           r'vote</span>(.*?)</p>', page)]
    assert claimed == [("against", "Rep. Kurk")], (
        f"HB 110's page of 10 February 1999 credits {claimed}: " + txt[:500])
    also = re.search(r"Also spoke during this bill (.*?) the record does not say", txt)
    assert also and also.group(1).strip() == "Rep. Burling , Rep. Mirski , Rep. Vaillancourt", (
        "those who spoke on HB 110's report before the motion to recommit, and only they, "
        f"are not the page's unplaced speakers: {also and also.group(1)!r}")
    # One motion on the day does not claim a speech made before it was moved:
    # HB 232 of 4 January 2024, whose record holds its tabling alone.
    spoke = [{"bill": "HB232-FN", "side": "against", "names": ["Brian Sullivan"],
              "tally": (190, 182), "inline_motion": None,
              "moved_since": ["that HB 232-FN, adopting section 1910 OSHA standards for public "
                              "sector employees in New Hampshire, be laid on the table"]},
             {"bill": "HB232-FN", "side": "for", "names": ["Infantine"], "tally": (190, 182),
              "inline_motion": None,
              "moved_since": ["that HB 232-FN, adopting section 1910 OSHA standards for public "
                              "sector employees in New Hampshire, be laid on the table"]}]
    lay = item("HB232", "2023-2024", "Lay HB232 on Table", "MA", "RC", "190", "182")
    assert BSP.speakers_for(spoke, "HB232", lay, sole=True)[0] == {"for": [], "against": []} and \
        BSP.unplaced(spoke, "HB232", [lay]) == ["Brian Sullivan", "Infantine"], (
        "the two who spoke on HB 232's amendment are credited to the motion that tabled it")
    # ...and still claims one made on it: no motion was moved in between.
    after = [dict(spoke[0], moved_since=[])]
    assert BSP.speakers_for(after, "HB232", lay, sole=True)[0]["against"] == ["Brian Sullivan"]
    return "ok", ("Arndt is not for tabling HB 374; HR 20's debate stays with its report "
                  "across a tabling motion that lost; HB 110's page credits Kurk alone and "
                  "names the other three once; HB 232's tabling claims no speech made before it")


@check("data", "no history tells a row whose LSR is another measure's, and no bill's own "
       "row or roll call is left under a number typed another way",
       needs=("narrative", "narrate_archive", "rollcall_parser"))
def _own_lsr_on_disk(N, NA, RP):
    """The audit of 30 September, re-measured on the built files, from the
    dockets and data/bills.json rather than through own_rows.

    A history row whose own LSR, year and number, is a different bill's of
    the same term; one whose LSR no bill carries, under a number whose own
    LSR began on another day (a number used twice in a term); a narratives
    key no bill carries whose rows name exactly one bill's LSR; a roll call
    filed as procedural, or keyed, under a bill number typed some other way;
    a member's ballot under one. On the build of 30 September: 76 such rows
    found in 38 of the 43 histories, 27 keys, seven roll calls and 893
    ballots. A row is found by its text, so one an older decade's reader
    joins to the next is not -- this undercounts, and never invents one."""
    fb, fn = Path("data/bills.json"), Path("narratives.json")
    if not (fb.exists() and fn.exists()):
        return "skip", "no data/bills.json or narratives.json"
    found = dict(NA.dockets())
    if Path("Docket.txt").exists():
        found["current"] = "Docket.txt"
    if not found:
        return "skip", "no docket on this disk"
    lsrs = N.load_lsrs(fb)
    narr = _narratives()
    owner = {}
    for t, recs in lsrs.items():
        for b, (y, n) in recs.items():
            if n:
                owner.setdefault((t, y, n), set()).add(b)
    sq = lambda s: re.sub(r"\s+", " ", s or "").strip().lower()
    told, stray, checked = [], [], 0
    for path in found.values():
        rows = {}
        with open(path, encoding="utf-8-sig", errors="replace") as fh:
            for line in fh:
                p = line.rstrip("\n").split("|")
                if len(p) < 7 or not p[0].strip().isdigit():
                    continue
                t = N.P.term_of(p[0].strip())
                rows.setdefault((t, p[3].strip()), []).append(
                    (p[0].strip(), N._lsr_num(p[1]), p[2].split(" ")[0], p[5]))
        for (t, key), rs in rows.items():
            rec = lsrs.get(t, {}).get(key)
            if not rec:
                names = {next(iter(owner[(t, y, n)])) for y, n, _d, _x in rs
                         if len(owner.get((t, y, n), ())) == 1}
                if names and key in (narr.get(t) or {}) and \
                        not all((t, key, n) in N.NOT_MOVED for _y, n, _d, _x in rs):
                    stray.append(f"{t} {key!r} (rows of {', '.join(sorted(names))})")
                continue
            own = rec[1]
            if not own or all(n != own for _y, n, _d, _x in rs):
                continue
            mine = {sq(N.clean(x)) for _y, n, _d, x in rs if n == own}
            began = min(datetime_of(d) for _y, n, d, _x in rs if n == own)
            raws = {sq(e.get("raw")) for e in ((narr.get(t) or {}).get(key) or {}).get("events") or ()}
            for y, n, d, x in rs:
                # A row with no LSR is kept by own_rows: nothing says whose.
                if n == own or not n:
                    continue
                whose = owner.get((t, y, n), set()) - {key}
                reused = not owner.get((t, y, n)) and datetime_of(
                    min((dd for _y, nn, dd, _x in rs if nn == n), key=datetime_of)) != began
                if not (whose or reused):
                    continue
                checked += 1
                c = sq(N.clean(x))
                if c not in mine and c in raws:
                    who = f", {' and '.join(sorted(whose))}'s" if whose else ""
                    told.append(f"{t} {key}: {x.strip()[:50]!r} (LSR {y}-{n}{who})")
    assert not told, (f"{len(told)} history row(s) tell another measure's docket row "
                      "(rebuild the narratives if narrative.py is newer): " + "; ".join(told[:4]))
    assert not stray, (f"{len(stray)} narratives key(s) no bill carries still hold a bill's "
                       "own rows: " + "; ".join(stray[:6]))
    # The roll calls, and every member's ballot on one.
    typed = []
    rc = Path("rollcalls.json")
    if rc.exists():
        for t, byb in json.loads(rc.read_text(encoding="utf-8")).items():
            for b, rs in byb.items():
                for r in rs:
                    n = RP.bill_number(r.get("bill"))
                    # 2009's SR 1 is filed under its own name on purpose:
                    # rollcall_parser.OTHER_MEASURE.
                    if RP.other_measure(r) and b == r.get("bill"):
                        continue
                    if (b == "_procedural" and n) or (b != "_procedural" and
                                                      (b != n or r.get("bill") != n)):
                        typed.append(f"{r.get('year')} {r.get('body')} {r.get('number')} "
                                     f"{r.get('bill')!r} under {b!r}")
    mv = Path("data/member_votes.json")
    ballots = 0
    if mv.exists():
        # Every ballot under each spelling of a bill number (_ballot_census),
        # so the number is asked once for each spelling and not once a ballot.
        for bill, cast in _ballot_census()["bills"].items():
            n = RP.bill_number(bill)
            if n and n != bill:
                if ballots < 3:
                    typed.append(f"ballot on {bill!r}")
                ballots += cast
    assert not typed, (f"roll calls or ballots under a bill number typed another way "
                       f"({ballots} ballots): " + "; ".join(typed[:6]))
    return "ok", (f"{checked:,} docket rows whose LSR is another measure's are in no "
                  "history; no stray key holds a bill's rows; every roll call and ballot "
                  "is under its bill's own number")


def datetime_of(mdy):
    """A docket entry stamp's date, "01/19/2011", as a comparable tuple."""
    try:
        m, d, y = (int(x) for x in mdy.split("/"))
        return (y, m, d)
    except ValueError:
        return (0, 0, 0)


@check("session", "the clerk's as-of date dates a row, but never ahead of what it answers",
       needs=("narrative", "docket_vocab"))
def _session_as_of_dates(N, V):
    """A database-era floor row that states no date is dated by the moment it
    was entered -- unless the clerk wrote the day it was done.

    "[done during 1/4/2012 morning veto session]" was entered on 30 November
    2011 and put four of January's veto votes on a November page. But
    "[Recess of 6/5/13]" names the sitting the House was in recess of, and
    dated by it HB 224's non-concurrence would come a day BEFORE the Senate
    amendment it refused; the Senate's "[05/06/04]" on HB 369 would have it
    accede to a House request six days before the House made it. Real rows,
    each case once.
    """
    from datetime import datetime as _dt
    saved = (N.CORRECTIONS, N.TERM)
    rows = {
        ("HB218", "2011"): [
            "2011|0291|11/30/2011 09:57:16 AM|HB218|H|Veto Sustained: RC 231-128 "
            "Lacking Rquired Two Thirds Vote, [done during 1/4/2012 morning veto "
            "session]; HJ 76, PG.2297-2300|11/30/2011 09:57:16 AM"],
        ("HB224", "2013"): [
            "2013|0305|06/06/2013 10:43:40 AM|HB224|S|Ought to Pass with Amendment "
            "1947s, MA, VV; OT3rdg|06/06/2013 10:43:40 AM",
            "2013|0305|06/12/2013 11:14:47 AM|HB224|H|House Non-Concurs with Senate "
            "AM #1947s and Requests C of C (Rep. Shurtleff): MA VV [Recess of "
            "6/5/13]; HJ49, PG.1650|06/12/2013 11:14:47 AM"],
        ("HB369", "2004"): [
            "2004|0125|05/06/2004 09:36:17 PM|HB369|S|Ought to Pass as Amended{1544},"
            "(New Title), MA, VV; OT3rdg; SJ 15, Pg.448|05/06/2004 09:36:17 PM",
            "2004|0125|05/13/2004 10:54:26 AM|HB369|H|House Nonconc with Sen Am req "
            "Conf Comm, Rep Mock MA VV;   HJ 39, p 1547|05/13/2004 10:54:26 AM",
            "2004|0125|05/13/2004 04:39:38 PM|HB369|S|Senator Peterson Accede to House "
            "Request for C of C, MA, VV [05/06/04]; SJ 15-A, Pg.466|05/13/2004 04:39:38 PM"],
        ("HB189", "2001"): [
            "2001|0133|05/09/2001 09:37:36 AM|HB189|S|Special Order To [05/17/01], MA, "
            "VV; SJ 12, Pg.262|05/09/2001 09:37:36 AM"],
        # AN ENROLMENT DONE IN RECESS is not told before the vote it enrolled:
        # SB 48 of 2015 was "enrolled" on 9 April, six days before the House
        # passed it. HB 1110 of 2014's, done in recess after both votes,
        # keeps the day it names.
        ("SB48", "2015"): [
            "2015|0118|04/15/2015 11:02:16 AM|SB48|H|Ought to Pass: MA VV; HJ 34, PG. 1554"
            "|04/15/2015 11:02:16 AM",
            "2015|0118|04/29/2015 12:29:48 PM|SB48|S|Enrolled (In recess 4/9/2015); SJ 12"
            "|04/29/2015 12:29:48 PM"],
        ("HB1110", "2014"): [
            "2014|2053|05/08/2014 11:20:14 AM|HB1110|S|Ought to Pass: MA, VV; OT3rdg; SJ 12"
            "|05/08/2014 11:20:14 AM",
            "2014|2053|05/22/2014 06:31:24 PM|HB1110|H|Enrolled (In recess of 5/15/2014)"
            "|05/22/2014 06:31:24 PM"],
        # Nor after the governor it went to: SB 447 of 2016 was entered five
        # days after the signature, and is told on the day of the House vote
        # before it. HB 273 of 2021's, entered the day the governor signed,
        # keeps that day, ahead of the signature.
        ("SB447", "2016"): [
            "2016|2955|1/20/2016 12:00:00 AM|SB447|H|Ought to Pass : MA DV 275-71 01/20/2016 "
            "HJ 8 P. 2|1/20/2016 12:00:00 AM",
            "2016|2955|1/26/2016 12:00:00 AM|SB447|S|Enrolled (In recess 01/14/2016); SJ 2"
            "|1/26/2016 12:00:00 AM",
            "2016|2955|4/20/2016 12:00:00 AM|SB447|S|Signed by the Governor on 01/21/2016; "
            "Chapter 0001 SJ 3|4/20/2016 12:00:00 AM"],
        ("HB273", "2021"): [
            "2021|0110|5/6/2021 12:00:00 AM|HB273|S|Ought to Pass : RC 23Y-0N, MA; OT3rdg; "
            "05/06/2021; SJ 14|5/6/2021 12:00:00 AM",
            "2021|0110|5/11/2021 12:00:00 AM|HB273|H|Enrolled (in recess of) 04/09/2021 HJ 7 "
            "P. 103|5/11/2021 12:00:00 AM",
            "2021|0110|5/12/2021 12:00:00 AM|HB273|H|Signed by Governor Sununu 05/11/2021; "
            "Chapter 30; Eff: 05/11/2021|5/12/2021 12:00:00 AM"],
        # A DAY'S ROWS IN THE ORDER THEY WERE ENTERED, dated or not: the
        # House defeated HB 705's conference report at 5:07 PM, reconsidered
        # at 5:08 and adopted it at 5:14. The two floor rows are dated at
        # midnight and "Defeated" by its minute, and the history put the
        # defeat last -- on a bill that became law.
        ("HB705", "2003"): [
            "2003|0462|06/24/2003 05:07:35 PM|HB705|H|Conf Comm Report Defeated "
            "RC(159-172);  HJ 51, p1628-1630|06/24/2003 05:07:35 PM",
            "2003|0462|06/24/2003 05:08:03 PM|HB705|H|Rep Mock moved to Reconsider, MA "
            "VV;  HJ 51, p1633|06/24/2003 05:08:03 PM",
            "2003|0462|06/24/2003 05:14:32 PM|HB705|H|Conf Comm Report Adopted VV; HJ 51, "
            "p1633|06/24/2003 05:14:32 PM"],
    }
    try:
        N.CORRECTIONS = []
        got, every, dated = {}, {}, {}
        for (bill, session), lines in rows.items():
            recs = []
            for x in lines:
                p = x.split("|")
                recs.append({"lsr": f"{p[0]}-{p[1]}", "session": p[0], "body": p[4],
                             "desc": p[5], "flags": [],
                             "created": _dt.strptime(p[2], "%m/%d/%Y %I:%M:%S %p")})
            N.TERM = N.P.term_of(session)
            evs = N.build(bill, recs)["events"]
            every[bill] = [e["raw"][:24] for e in evs]
            dated[bill] = [(e["date"], e["raw"][:8]) for e in evs]
            got[bill] = [(e["body"], e["date"], e["raw"][:24])
                         for e in evs if e["type"] in ("floor", "veto_override")]
        assert [x[:20] for x in every["HB705"]] == [
                "Conf Comm Report Def", "Rep Mock moved to Re", "Conf Comm Report Ado"], (
            f"a day's rows are not in the order the clerk entered them: {every['HB705']}")
        assert [d for _, d, _ in got["HB218"]] == ["2012-01-04"], (
            f"the clerk's 'done during 1/4/2012' did not date the veto vote: {got['HB218']}")
        assert ("H", "2013-06-12") in [(b, d) for b, d, _ in got["HB224"]], (
            "a row done in recess of 5 June 2013 was moved onto 5 June, ahead "
            f"of the Senate amendment it refused: {got['HB224']}")
        assert ("S", "2004-05-13") in [(b, d) for b, d, _ in got["HB369"]], (
            "the Senate's accession was dated before the House request it "
            f"answered: {got['HB369']}")
        # Put back on its own day, it must also go back to its place in it:
        # the House asked at 10:54 AM, the Senate acceded at 4:39 PM.
        assert [(b, d) for b, d, _ in got["HB369"]] == [
            ("S", "2004-05-06"), ("H", "2004-05-13"), ("S", "2004-05-13")], (
            "the Senate's accession, put back on 13 May, still comes before "
            f"the House request it answered that morning: {got['HB369']}")
        assert [d for _, d, _ in got["HB189"]] == ["2001-05-09"], (
            f"a special order's date was read as the day it was done: {got['HB189']}")
        enrolled = dated
        assert enrolled["SB48"] == [("2015-04-15", "Ought to"), ("2015-04-29", "Enrolled")], (
            "an enrolment done in recess was told before the House vote it "
            f"enrolled: {enrolled['SB48']}")
        assert enrolled["HB1110"][-1] == ("2014-05-15", "Enrolled"), (
            "an enrolment done in recess after both votes lost the day it "
            f"names: {enrolled['HB1110']}")
        assert enrolled["SB447"] == [("2016-01-20", "Ought to"), ("2016-01-20", "Enrolled"),
                                     ("2016-01-21", "Signed b")], (
            "an enrolment done in recess was told after the governor signed "
            f"the bill: {enrolled['SB447']}")
        assert enrolled["HB273"] == [("2021-05-06", "Ought to"), ("2021-05-11", "Enrolled"),
                                     ("2021-05-11", "Signed b")], (
            "an enrolment entered the day the governor signed lost that day or "
            f"its place ahead of the signature: {enrolled['HB273']}")
        return "ok", ("'done during' dates a veto vote; a day in recess, an "
                      "answer ahead of its request and a special order's "
                      "target date do not; a day's rows keep the order they "
                      "were entered in")
    finally:
        N.CORRECTIONS, N.TERM = saved


@check("narrative", "a House floor day the 1999-2006 docket cut into rows is read as one "
       "entry, and a question its own clause says lost is not told as carried",
       needs=("narrative", "docket_vocab", "docket_era_1999"))
def _docket_1999_cut_rows(N, V, E):
    """HB 605 of 1999 was told as killed -- its history, the 14 April 1999
    sitting and the consent grouping -- because the database cut the House's
    one entry for that day into three rows and the first, read alone, is "ITL
    Report adopted". Whole, it is the consent calendar reconsidered and the
    bill recommitted on Rep. Mock's motion, and it passed on 13 May. The
    1989 and 2007 eras had a joiner and this one had none, and docket_vocab
    returns rows unjoined when an era has none. HB 110 of 1999 was told as
    tabled and then passed, where the House voted the tabling down and killed
    it.

    Separately, a question whose words sound carried ("Lay on Table",
    "Passed") was made adopted whatever its own clause said: 2006 HB 1240 was
    told as passed on the day passage failed 141-181, as were four other 2006
    House bills, and 98 events in all. Each rule is tested on the rows that
    showed it, beside a row each must leave alone."""
    from datetime import datetime as _dt
    tup = lambda lines, body=None: [
        (_dt.strptime(p[2], "%m/%d/%Y %I:%M:%S %p"), "", body or p[4], p[5])
        for p in (x.split("|") for x in lines)]
    rows = _DOCKET_CUT_1999
    assert callable(getattr(E, "join_rows", None)), (
        "docket_era_1999 has no join_rows, and docket_vocab reads its rows unjoined")
    joined = {b: [r[3] for r in E.join_rows(tup(rows[b]))] for b in rows}
    whole = " ".join(x.split("|")[5].strip() for x in rows["HB605"][1:])
    assert joined["HB605"][1:] == [whole], (
        f"HB 605's 14 April 1999 entry is not read whole: {joined['HB605']}")
    for b, why in (("HB110", "a lowercase word"), ("HB94", "a bare result"),
                   ("HB278", "the page of a broken citation"), ("HR10", "a bare result")):
        assert len(joined[b]) == 1, f"{b}'s row that opens on {why} was not joined: {joined[b]}"
    assert len(joined["HB317"]) == 2, (
        "2006 HB 317's 'ref to Ways & Means', typed as an entry of its own after a "
        f"decided question, was joined to it: {joined['HB317']}")
    assert len(E.join_rows(tup(rows["HB110"], body="S"))) == 2, (
        "a Senate row was joined; only the House's floor day is one entry cut")

    saved = (N.CORRECTIONS, N.TERM)
    try:
        N.CORRECTIONS = []
        got, told, votes = {}, {}, {}
        for b, lines in rows.items():
            recs = _docket_rows(lines)
            N.TERM = N.P.term_of(recs[0]["session"])
            r = N.build(b, recs)
            got[b] = [(e["date"], e.get("action"), e.get("motion"))
                      for e in r["events"] if e["type"] == "floor"]
            votes[b] = [(e.get("motion"), e.get("vote_kind"), e.get("yeas"), e.get("nays"))
                        for e in r["events"] if e["type"] == "floor"]
            told[b] = r.get("narrative") or ""
    finally:
        N.CORRECTIONS, N.TERM = saved
    assert got["HB605"] == [("1999-04-14", "Rerefer to Committee", "MA")], (
        f"HB 605's 14 April 1999 entry is not its recommittal: {got['HB605']}")
    assert "send it back to committee" in told["HB605"] and \
        "voted to kill it" not in told["HB605"], (
        "HB 605's history still says the House killed it: " + told["HB605"][-160:])
    # Whole, the line's last carried question is the report to kill it; its
    # two failed motions are told ahead of it, each with its own vote
    # (_docket_1999_questions), and neither is told as carried.
    assert got["HB110"] == [("1999-02-10", "Rerefer to Committee", "ML"),
                            ("1999-02-10", "Lay on Table", "ML"),
                            ("1999-02-10", "Inexpedient to Legislate", "MA")], (
        f"HB 110's 10 February 1999 entry is not two failed motions and the report to "
        f"kill it adopted: {got['HB110']}")
    assert "voted to lay it on the table" not in told["HB110"] and \
        "voted to pass it" not in told["HB110"], (
        "HB 110's history says it was tabled or passed: " + told["HB110"][-200:])
    assert got["HR10"] == [("1999-05-25", "Taken from the Table", "MA"),
                           ("1999-05-25", "Lay on Table", "MA")], (
        f"HR 10's tabling, carried and read whole, is no longer told: {got['HR10']}")
    assert got["HB1240"] == [("2006-02-15", "Ought to Pass with Amendment", "ML"),
                             ("2006-02-15", "Refer for Interim Study", "MA")], (
        f"2006 HB 1240's failed passage is not told as failed: {got['HB1240']}")
    assert "rejected a motion to pass it with changes" in told["HB1240"], (
        "2006 HB 1240's history does not say passage failed: " + told["HB1240"][-200:])
    assert got["HB162"] == [("2006-02-02", "Lay on Table", "ML")] and \
        got["SB42"] == [("2005-02-17", "Lay on Table", "MF")], (
        f"a tabling its own clause says lost is told as carried: {got['HB162']} {got['SB42']}")
    # A question read as lost keeps the count the House wrote after its
    # result; the Senate's, written before it, is not replaced by what follows.
    assert votes["HB162"] == [("ML", "RC", "140", "198")] and \
        votes["HB1240"][0] == ("ML", "RC", "141", "181") and \
        votes["SB128"] == [("ML", "RC", "144", "195")], (
        f"a House question that lost has no count: {votes['HB162']} {votes['HB1240']} "
        f"{votes['SB128']}")
    assert votes["SB301"] == [("MF", "", None, None)], (
        f"SB 301's tabling, lost on a division of 8 to 14, took the 'VV' written after "
        f"its result: {votes['SB301']}")
    assert [m for _d, _a, m in got["HB317"]] == ["MA"], (
        f"2006 HB 317's carried passage is no longer told as carried: {got['HB317']}")
    # The result the clerk put after a semicolon of its own.
    assert got["SB301"] == [("2000-03-09", "Lay on Table", "MF")] and \
        got["SB1"] == [("2006-09-26", "Lay on Table", "MF")], (
        f"a tabling whose result follows its own semicolon is told as carried: "
        f"{got['SB301']} {got['SB1']}")
    assert "rejected a motion to lay it on the table" in told["SB301"], told["SB301"][-160:]
    # A Senate question and its third reading, which came out differently.
    assert votes["SB108"] == [("MF", "RC", "10", "14")], (
        f"SB 108 of 1999's recommittal, which failed 10-14 on a roll call, is "
        f"{votes['SB108']}")
    assert "rejected a motion to send it back to committee on a roll call" in told["SB108"], (
        "SB 108's history does not say the recommittal failed: " + told["SB108"][-200:])
    assert votes["SB219"] == [("MF", "RC", "12", "12")], (
        f"SB 219 of 2000's third reading, which failed 12-12, is {votes['SB219']}")
    assert "voted to pass it" not in told["SB219"], (
        "SB 219's history says the Senate passed it on 3 February 2000: "
        + told["SB219"][-200:])
    return "ok", ("HB 605 is recommitted and HB 110 killed, read whole; HB 317's separate "
                  "referral stays apart; HB 1240's passage, HB 162's, SB 42's, SB 301's and "
                  "2006 SB 1's tablings lost; SB 108's recommittal and SB 219's third "
                  "reading lost")


